const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',finger:'<path d="M7 11v-1a5 5 0 0 1 10 0v4m-13-1v-3a8 8 0 0 1 16 0v3M10 20c2-3 1-6 1-10a1 1 0 0 1 2 0v7m-6-3c0 4-1 5-2 7m11-4c0 2-1 4-2 5m6-6c0 3-1 5-2 6"/>',wallet:'<path d="M20 8H5a2 2 0 0 1 0-4h13v4m2 0v12H5a2 2 0 0 1-2-2V6m13 6h5v4h-5z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',requests:'<path d="M7 3H5v18h14V3h-2M9 3h6v4H9zM8 12h8m-8 5h5"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',arrow:'<path d="M19 12H5m6-6-6 6 6 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4 8 8 0 1 0 20 14Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',check:'<path d="m5 12 4 4L19 6"/>',cross:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const content=document.querySelector('#content');let screen='home',result='success',cancelInteraction=()=>{};
const examples=[{type:'leave',title:'طلب إجازة',detail:'٣ نوفمبر · يوم واحد',state:'pending',label:'قيد المراجعة'},{type:'advance',title:'طلب سلفة',detail:'مثال توضيحي · ٥٠٠ ج.م',state:'approved',label:'موافق عليه'},{type:'leave',title:'طلب إجازة',detail:'٢٠ أكتوبر · يوم واحد',state:'declined',label:'غير معتمد'}];
function decorate(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));document.querySelector('.top .theme-toggle').innerHTML=icon(document.body.dataset.theme==='dark'?'sun':'moon');const n=document.querySelector('#theme-name');if(n)n.textContent=document.body.dataset.theme==='dark'?'منتصف الليل':'العاجي الدافئ';}
function render(next){cancelInteraction();screen=next;document.body.dataset.screen=next;content.replaceChildren();if(['advance','leave'].includes(next))renderForm(next);else content.append(document.querySelector('#'+next).content.cloneNode(true));const active=['advance','leave'].includes(next)?'requests':next;
 document.querySelector('.navigation').innerHTML=[['home','الرئيسية'],['attendance','الحضور'],['requests','طلباتي'],['profile','حسابي']].map(([key,label])=>`<button data-go="${key}" ${active===key?'aria-current="page"':''}>${icon(key==='attendance'?'finger':key)}<span>${label}</span></button>`).join('');decorate();if(next==='attendance')attendance();if(next==='requests')listRequests('all');window.scrollTo({top:0,behavior:'instant'});}
function renderForm(type){const advance=type==='advance';content.innerHTML=`<section class="view"><button class="back" data-go="home">${icon('arrow')}الرئيسية</button><div class="eyebrow">طلب جديد · محاكاة</div><h1>${advance?'طلب سلفة':'طلب إجازة'}</h1><p class="subtle">${advance?'اكتب المبلغ والسبب لعرض تجربة الطلب.':'حدد الفترة وأضف ملاحظة للإدارة.'}</p><form class="form"><label>${advance?'المبلغ':'من تاريخ'}${advance?'<div class="input-unit"><input name="amount" type="number" inputmode="decimal" min="1" max="99999" step="0.01" required placeholder="0"><span>ج.م</span></div>':'<input name="from" type="date" required>'}</label>${advance?'':'<label>إلى تاريخ<input name="to" type="date" required></label>'}<label>${advance?'السبب':'ملاحظة'}<textarea name="reason" maxlength="300" required placeholder="${advance?'سبب طلب السلفة…':'سبب طلب الإجازة…'}"></textarea></label><div class="form-note">هذه تجربة تصميم فقط. لا يتم إرسال الطلب أو حفظه، ولا تمثل الأرقام استحقاقات مالية.</div><button class="primary" type="submit">معاينة الطلب</button><div id="form-feedback" role="status"></div></form></section>`;
 const form=content.querySelector('form');form.addEventListener('submit',e=>{e.preventDefault();const from=form.elements.namedItem('from'),to=form.elements.namedItem('to');if(from&&to&&to.value<from.value){to.setCustomValidity('تاريخ النهاية يجب ألا يسبق البداية');to.reportValidity();return;}document.querySelector('#form-feedback').className='form-result';document.querySelector('#form-feedback').textContent='انتهت المعاينة. لم يتم إرسال أو حفظ أي طلب.';});form.addEventListener('input',()=>{const to=form.elements.namedItem('to');if(to)to.setCustomValidity('');});}
function listRequests(filter){document.querySelector('#request-list').innerHTML=examples.filter(r=>filter==='all'||(filter==='pending'?r.state==='pending':r.state!=='pending')).map(r=>`<article class="request"><span>${icon(r.type==='leave'?'calendar':'wallet')}</span><div><h3>${r.title}</h3><p>${r.detail}</p></div><span class="request-badge ${r.state}">${r.label}</span></article>`).join('');}
function attendance(){
 const hold=document.querySelector('#hold'),control=document.querySelector('.mechanical-control'),ring=document.querySelector('.progress-ring circle'),title=document.querySelector('#orb-title'),caption=document.querySelector('#orb-caption'),status=document.querySelector('#attendance-status');
 let frame=0,start=0,timers=[],running=false,completed=false,pointer=null,heldKey=null,pressing=false;
 const options=[...document.querySelectorAll('[data-result]')],mode=document.querySelector('#attendance-mode'),resetButton=document.querySelector('#reset-attendance');
 const stage=value=>{control.dataset.stage=value;};
 const release=()=>{pressing=false;pointer=null;heldKey=null;cancelAnimationFrame(frame);frame=0;control.dataset.pressed='false';if(!running&&!completed){stage('idle');ring.style.strokeDashoffset='754';title.textContent='اضغط مطولًا';caption.textContent='لتجربة تسجيل الحضور';}};
 const reset=()=>{release();timers.forEach(clearTimeout);timers=[];running=false;completed=false;hold.disabled=false;mode.disabled=false;resetButton.disabled=false;options.forEach(b=>b.disabled=false);stage('idle');ring.style.strokeDashoffset='754';title.textContent='اضغط مطولًا';caption.textContent='لتجربة تسجيل الحضور';hold.querySelector('[data-icon]').innerHTML=icon('finger');status.textContent='لا يتم استخدام موقعك أو إنشاء سجل حضور.';};
 const run=()=>{running=true;pressing=false;control.dataset.pressed='false';hold.disabled=true;mode.disabled=true;resetButton.disabled=true;options.forEach(b=>b.disabled=true);stage('locating');title.textContent='تحديد الموقع';caption.textContent='محاكاة فقط';status.textContent='محاكاة تحديد الموقع — لا نطلب موقع الجهاز.';
 timers.push(setTimeout(()=>{stage('verifying');title.textContent='جارٍ التحقق';status.textContent='محاكاة التحقق من الخادم — لا يوجد اتصال بخادم.';},1100));
 timers.push(setTimeout(()=>{
 if(result!=='success'){running=false;completed=true;stage('failure');title.textContent='تعذّر التحقق';caption.textContent='نتيجة محاكاة';hold.querySelector('[data-icon]').innerHTML=icon('cross');mode.disabled=false;resetButton.disabled=false;options.forEach(b=>b.disabled=false);status.textContent='فشل توضيحي للتحقق. لم تُرسل بيانات ولم يُسجّل حضور.';return;}
 // This event is exclusively a fictional server result. A real client must wait
 // for verified backend attendance confirmation before entering this sequence.
 const checkout=mode.value==='checkout';control.dataset.confirmation=checkout?'checkout':'checkin';stage('igniting');completed=true;
 title.textContent='تمت المحاكاة';caption.textContent='لا يوجد سجل فعلي';hold.querySelector('[data-icon]').innerHTML=icon('check');
 status.innerHTML='<span class="ignition-demo">محاكاة فقط · بيانات خيالية</span><strong class="ignition-title">'+(checkout?'تم تسجيل انصرافك':'بدأ يومك يا أحمد')+'</strong>'+(checkout?'':'<span class="ignition-message">تم تسجيل حضورك بنجاح</span>')+'<time class="ignition-time">وقت توضيحي مؤكد بالمحاكاة · '+(checkout?'09:02 مساءً':'12:03 ظهرًا')+'</time>';
 timers.push(setTimeout(()=>{stage('success');running=false;mode.disabled=false;resetButton.disabled=false;options.forEach(b=>b.disabled=false);title.textContent=checkout?'انتهت الوردية':'الوردية بدأت';caption.textContent='حالة توضيحية فقط';},checkout?1400:2600));
 },2400));};
 const begin=()=>{if(running||completed||pressing)return false;pressing=true;start=performance.now();control.dataset.pressed='true';stage('holding');title.textContent='استمر بالضغط';caption.textContent='أبقِ الضغط حتى اكتمال الحلقة';const tick=now=>{if(!pressing)return;const progress=Math.min((now-start)/1400,1);ring.style.strokeDashoffset=String(754*(1-progress));if(progress<1)frame=requestAnimationFrame(tick);else{frame=0;run();}};frame=requestAnimationFrame(tick);return true;};
 hold.addEventListener('pointerdown',e=>{if(e.button!==0||e.isPrimary===false||pressing||running||completed)return;e.preventDefault();hold.focus({preventScroll:true});if(!begin())return;pointer=e.pointerId;try{hold.setPointerCapture(e.pointerId);}catch{release();}});
 ['pointerup','pointercancel','lostpointercapture'].forEach(n=>hold.addEventListener(n,e=>{if(e.pointerId===pointer)release();}));
 hold.addEventListener('contextmenu',e=>e.preventDefault());
 hold.addEventListener('keydown',e=>{if(e.key!==' '&&e.key!=='Enter')return;e.preventDefault();if(e.repeat||pressing||running||completed)return;if(begin())heldKey=e.key;});
 hold.addEventListener('keyup',e=>{if(e.key===heldKey){e.preventDefault();release();}});
 hold.addEventListener('blur',release);resetButton.onclick=()=>{if(!running)reset();};mode.onchange=()=>{if(!running)reset();};
 const hidden=()=>{if(document.hidden)reset();};document.addEventListener('visibilitychange',hidden);cancelInteraction=()=>{reset();document.removeEventListener('visibilitychange',hidden);};
 options.forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.result===result));b.onclick=()=>{if(running)return;result=b.dataset.result;reset();options.forEach(el=>el.setAttribute('aria-pressed',String(el===b)));};});
}

document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){render(go.dataset.go);return;}if(e.target.closest('.theme-toggle')){const dark=document.body.dataset.theme!=='dark';document.body.dataset.theme=dark?'dark':'light';document.querySelector('.logo').src=dark?'../../assets/cashier-header-logo-white-tight.svg':'../../assets/mini-print-logo.svg';document.querySelector('meta[name="theme-color"]').content=dark?'#101d23':'#f5f1e9';decorate();}const filter=e.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===filter));listRequests(filter.dataset.filter);}});
const previewTheme=new URLSearchParams(window.location.search).get('theme');
if(previewTheme==='light'){document.body.dataset.theme='light';document.querySelector('.logo').src='../../assets/mini-print-logo.svg';document.querySelector('meta[name="theme-color"]').content='#f5f1e9';}
render(new URLSearchParams(window.location.search).get('screen')==='attendance'?'attendance':'home');
